List<int> filterEven(List<int> numbers) {
  return numbers.where((n) => n % 2 == 0).toList();
}

void main() {
  print(filterEven([1, 2, 3, 4, 5]));
  print(filterEven([1, 3, 5]));
  print(filterEven([2, 4, 6]));
}

