void main() {
  test('Group mixed lengths', () {
    final result = groupByLength(['a', 'bb', 'ccc', 'dd']);
    expect(result[1], equals(['a']));
    expect(result[2], equals(['bb', 'dd']));
    expect(result[3], equals(['ccc']));
  });

  test('Empty list', () {
    expect(groupByLength([]), equals({}));
  });

  test('Same length', () {
