exercises.solutionCode:
Map<int, List<String>> groupByLength(List<String> words) {
  final result = <int, List<String>>{};

  for (final word in words) {
    final len = word.length;
    if (!result.containsKey(len)) {
      result[len] = [];
    }
    result[len]!.add(word);
  }

  return result;
}

void main() {
  print(groupByLength(['a', 'bb', 'ccc', 'dd']));
  print(groupByLength([]));
}
